// Functional component
function StatusBadge() {
  return (
    <div className="badge">
      <span>Status: ONLINE</span>
    </div>
  );
}

// Parent component nesting children
export default function Dashboard() {
  return (
    <main>
      <StatusBadge />
      <h1>Mission Control</h1>
    </main>
  );
}

// Define the component with props
function TelemetryCard({ title, value, unit }) {
  return (
    <div className="card">
      <h3>{title}</h3>
      <span>{value} {unit}</span>
    </div>
  );
}

// Use with different data
<TelemetryCard title="Speed" value={12} unit="Warp" />
<TelemetryCard title="Fuel" value={98} unit="%" />

import { useState } from 'react';

function ThrusterControl() {
  const [thrust, setThrust] = useState(0);
  const [warning, setWarning] = useState(false);

  const boost = () => {
    const newThrust = thrust + 10;
    setThrust(newThrust);
    setWarning(newThrust > 80);
  };

  return (
    <div>
      <p>Thrust: {thrust}%</p>
      {warning && <p style={{color:'red'}}>OVERLOAD WARNING!</p>}
      <button onClick={boost}>Boost</button>
    </div>
  );
}

import { useState, useEffect } from 'react';

function MissionClock() {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    // Run after mount
    const interval = setInterval(() => {
      setTime(new Date());
    }, 1000);

    // Cleanup on unmount
    return () => clearInterval(interval);
  }, []); // Empty array = run once

  return <p>{time.toLocaleTimeString()}</p>;
}

const missions = [
  { id: 1, name: 'Alpha Centauri', status: 'Active' },
  { id: 2, name: 'Proxima Base', status: 'Standby' },
  { id: 3, name: 'Kepler-442', status: 'Complete' },
];

function MissionList() {
  return (
    <ul>
      {missions.map(mission => (
        <li key={mission.id}>
          {mission.name} — {mission.status}
        </li>
      ))}
    </ul>
  );
}

import { createContext, useContext, useState } from 'react';

const ThemeContext = createContext('dark');

function App() {
  const [theme, setTheme] = useState('dark');
  return (
    <ThemeContext.Provider value={theme}>
      <Dashboard />
      <button onClick={() => setTheme('light')}>Switch Theme</button>
    </ThemeContext.Provider>
  );
}

function Dashboard() {
  const theme = useContext(ThemeContext);
  return <div className={`panel ${theme}`}>Theme: {theme}</div>;
}

// Custom hook
function useTelemetry(endpoint) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(endpoint)
      .then(res => res.json())
      .then(json => {
        setData(json);
        setLoading(false);
      });
  }, [endpoint]);

  return { data, loading };
}

// Usage in any component
function SensorPanel() {
  const { data, loading } = useTelemetry('/api/sensors');
  if (loading) return <p>Loading...</p>;
  return <div>{data.reading}</div>;
}
